using System;using System.Collections.Generic;using WildsEngine.Discoveries.Abstractions.Consequences;using WildsEngine.Discoveries.Abstractions.Narratives;using WildsEngine.Discoveries.Abstractions.Outcomes;using WildsEngine.Discoveries.Abstractions.Services;using WildsEngine.Discoveries.Abstractions.Truths;using WildsEngine.Discoveries.Narratives;
namespace WildsEngine.Discoveries.Outcomes { internal sealed class DiscoveryOutcomeSurface:IDiscoveryOutcomeSurface { private readonly IWildsServiceClock _clock;public DiscoveryOutcomeSurface(IWildsServiceClock c,IDiscoveryTruthSurface t,IDiscoveryConsequenceSurface q){_clock=c;Truths=t;Consequences=q;}public IDiscoveryTruthSurface Truths{get;}public IDiscoveryConsequenceSurface Consequences{get;}public IDiscoveryCompetingNarrativesResult Relate(IDiscoveryNarrativeCompositionResult composition){var rels=new List<IDiscoveryNarrativeGroupRelationship>();for(var i=0;i<composition.Groups.Count;i++)for(var j=i+1;j<composition.Groups.Count;j++){var ds=new List<IDiscoveryNarrativeCompositionDecision>();foreach(var d in composition.Decisions)if((Contains(composition.Groups[i],d.Left)&&Contains(composition.Groups[j],d.Right))||(Contains(composition.Groups[i],d.Right)&&Contains(composition.Groups[j],d.Left)))ds.Add(d);rels.Add(new DiscoveryNarrativeGroupRelationship(composition.Groups[i],composition.Groups[j],ds));}return new DiscoveryCompetingNarrativesResult(Guid.NewGuid(),composition,rels,_clock.GetUtcNow());}private static bool Contains(IDiscoveryNarrativeGroup g,object m){foreach(var x in g.Members)if(ReferenceEquals(x,m))return true;return false;} } }
